-- Usar SOMENTE em banco vazio. Não executar novamente se as tabelas já existem.
CREATE DATABASE IF NOT EXISTS stockcontrol CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE stockcontrol;
CREATE TABLE categorias (id INT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(100) NOT NULL UNIQUE,descricao VARCHAR(255));
CREATE TABLE fornecedores (id INT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(150) NOT NULL,cnpj VARCHAR(14) UNIQUE,telefone VARCHAR(20),email VARCHAR(150),endereco VARCHAR(255),ativo BOOLEAN NOT NULL DEFAULT TRUE,criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE usuarios (id INT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(150) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,senha VARCHAR(255) NOT NULL,ativo BOOLEAN NOT NULL DEFAULT TRUE,criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
